1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
9	
10	/**
11	 * Validates the optional owner postcode. Runs only WHEN a postcode is present: an owner created
12	 * without a postcode is accepted unchanged (the request contract stays backward-compatible).
13	 *
14	 * <p>When present, the postcode must be exactly four digits. For a city with a known region it must
15	 * also fall within that region's inclusive range (Sydney/NSW 2000-2099, Melbourne/VIC 3000-3099,
16	 * Brisbane/QLD 4000-4099); a city with no known region accepts any 4-digit postcode. Anything else
17	 * is rejected with {@link InvalidPostcodeException} (400). The value is stored and returned as
18	 * given, so this step only validates and does not mutate the body.
19	 */
20	public class RequirePostcode {
21	
22	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
23	
24	    /** City -> canonical region (matching the mapper's locality table). */
25	    private static final Map<String, String> CITY_REGION = Map.of(
26	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    /** Region -> inclusive 4-digit postcode range {low, high}. */
29	    private static final Map<String, int[]> REGION_RANGE = Map.of(
30	            "NSW", new int[] {2000, 2099},
31	            "VIC", new int[] {3000, 3099},
32	            "QLD", new int[] {4000, 4099});
33	
34	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
35	        String postcode = request.getPostcode();
36	        if (postcode == null || postcode.isBlank()) {
37	            return; // optional when absent
38	        }
39	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
40	            throw new InvalidPostcodeException(postcode);
41	        }
42	        String region = CITY_REGION.get(request.getCity());
43	        int[] range = region == null ? null : REGION_RANGE.get(region);
44	        if (range != null) {
45	            int value = Integer.parseInt(postcode);
46	            if (value < range[0] || value > range[1]) {
47	                throw new InvalidPostcodeException(postcode);
48	            }
49	        }
50	    }
51	}
