1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Normalizes owner addresses to a canonical stored form.
8	 *
9	 * <p>Rules: trim, collapse internal whitespace runs to a single space, upper-case, and expand
10	 * the common abbreviations {@code ST -> STREET}, {@code RD -> ROAD} and {@code AVE -> AVENUE}
11	 * (whole words only). So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and
12	 * {@code "7 elm ave"} becomes {@code "7 ELM AVENUE"}. An address that is empty or only
13	 * whitespace normalizes to {@code ""}, which the required-field check rejects.
14	 *
15	 * <p>This is the single normalized form every part of the create pipeline uses: it is stored on
16	 * the owner (and hence returned), and both household duplicate detection and the shared household
17	 * id compare addresses through it.
18	 */
19	public final class AddressNormalizer {
20	
21	    private static final Map<String, String> ABBREVIATIONS = Map.of(
22	            "ST", "STREET",
23	            "RD", "ROAD",
24	            "AVE", "AVENUE");
25	
26	    private AddressNormalizer() {
27	    }
28	
29	    /** Canonical form of {@code input}; {@code ""} for {@code null}/blank input. */
30	    public static String normalize(String input) {
31	        if (input == null) {
32	            return "";
33	        }
34	        String collapsed = input.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
35	        if (collapsed.isEmpty()) {
36	            return "";
37	        }
38	        String[] tokens = collapsed.split(" ");
39	        StringBuilder sb = new StringBuilder(collapsed.length());
40	        for (int i = 0; i < tokens.length; i++) {
41	            if (i > 0) {
42	                sb.append(' ');
43	            }
44	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
45	        }
46	        return sb.toString();
47	    }
48	}
